/**
 * Generate `tables.inc` for the native RFD4-Proteina featuriser.
 *
 * 🔴 DERIVED, NEVER TYPED. Every table here already exists in `shared/rfd4p/`, and this port's own
 * recurring lesson is that a constant copied by hand is a second place for a convention to live.
 * `test/rfd4p-native-tables.test.js` fails when the generated file is stale, as
 * `test/native-featuriser-tables.test.js` does for the AF3 side.
 *
 *     node cuda/rfd4p/featurise/gen-tables.mjs > cuda/rfd4p/featurise/tables.inc
 */
import {
  UNIFIED_ATOM37_TOKENS, UNIFIED_ATOM37_ENCODING, UNIFIED_RESTYPE_ATOM37_MASK,
  ALLOWED_RESIDUE_TYPES, STANDARD_POLYMER_RESIDUES, LOCAL_LATENT_RESIDUE_SET,
  TokenType, TOKEN_TYPE_IDS, RESIDUES_BY_TOKEN_TYPE, ATOM37_NAMES,
  STANDARD_AA, STANDARD_RNA, STANDARD_DNA,
} from "../../../shared/rfd4p/encoding.js";
import {
  CHAIN_TYPE, BOND_TYPE, ELEMENT_TO_ATOMIC_NUMBER, METAL_ELEMENTS, STD_RESIDUE_CHARGES,
  STD_RESIDUE_AROMATIC, AA_RESIDUES, RNA_RESIDUES, DNA_RESIDUES, SCALAR_1BODY_ANNOTATIONS,
  NONSCALAR_1BODY_ANNOTATIONS, STD_RESIDUE_BONDS,
} from "../../../shared/rfd4p/pipeline/cif.js";
import { CONDITION_ENUMS, CONDITION_REGISTRY } from "../../../shared/rfd4p/pipeline/spec.js";
import { RECYCLE_SCHEDULES, DEFAULT_RECYCLE_SCHEDULE } from "../../../shared/rfd4p/flow.js";
import { ATOMIC_NUMBER_BY_ELEMENT } from "../../../shared/rfd4p/encoding.js";
import { getOrderedAtomNamesForResidue } from "../../../shared/rfd4p/output.js";
import {
  IDEAL_POLYHEDRA, STEREOISOMER_TEMPLATES, DOUBLE_BOND_TEMPLATES, CHIRAL_TYPE,
  MAX_OVERLAPPING_CENTERS,
} from "../../../shared/rfd4p/pipeline/chirality.js";

const str = (s) => JSON.stringify(s);
const out = [];
const w = (s) => out.push(s);

w("// GENERATED by cuda/rfd4p/featurise/gen-tables.mjs - do not edit.");
w("// The RFD4-Proteina vocabulary and conventions, derived from shared/rfd4p/ rather than typed.");
w("#pragma once");
w("#include <array>");
w("#include <cstdint>");
w("#include <string>");
w("#include <unordered_map>");
w("#include <unordered_set>");
w("#include <cmath>");
w("#include <vector>");
w("");
w("namespace rfd4p {");
w("namespace tables {");
w("");

const nTok = UNIFIED_ATOM37_TOKENS.length;
w(`constexpr int N_TOKENS = ${nTok};`);
w("constexpr int N_ATOM37 = 37;");
w(`constexpr int N_TOKEN_TYPES = ${Object.keys(TokenType).length};`);
w("");

w("// Every residue token, in vocabulary order; the index IS `residue_type`.");
w(`inline const std::array<const char*, ${nTok}> TOKENS = {`);
for (let i = 0; i < nTok; i += 8) {
  w("    " + UNIFIED_ATOM37_TOKENS.slice(i, i + 8).map(str).join(", ") + ",");
}
w("};");
w("");

w("// `TOKEN_TO_IDX`: a residue name to its vocabulary index, which IS its `residue_type`.");
w("inline const std::unordered_map<std::string, int> TOKEN_TO_IDX = {");
for (let i = 0; i < nTok; i += 4) {
  w("    " + UNIFIED_ATOM37_TOKENS.slice(i, i + 4)
    .map((name, k) => `{${str(name)}, ${i + k}}`).join(", ") + ",");
}
w("};");
w("");

w("// `token_group_by_idx`: each token's TOKEN TYPE id, which `convertToProteinaBatch` reads to");
w("// decide a token's type from its residue name. -1 where the group names no known type.");
w(`inline const std::array<int, ${nTok}> TOKEN_GROUP_TYPE = {`);
for (let i = 0; i < nTok; i += 12) {
  w("    " + UNIFIED_ATOM37_TOKENS.slice(i, i + 12).map((_, k) => {
    const grp = UNIFIED_ATOM37_ENCODING.token_group_by_idx[i + k];
    const id = TOKEN_TYPE_IDS[grp];
    return id === undefined ? -1 : id;
  }).join(", ") + ",");
}
w("};");
w("");

w("// `[token][slot]` atom names, empty where the token has no atom in that slot.");
w(`inline const std::array<std::array<const char*, 37>, ${nTok}> TOKEN_ATOMS = {{`);
for (const t of UNIFIED_ATOM37_TOKENS) {
  const atoms = UNIFIED_ATOM37_ENCODING.token_atoms[t];
  w("    {{" + Array.from({ length: 37 }, (_, s) => str(atoms[s] ?? "")).join(", ") + "}},");
}
w("}};");
w("");

w("// `restype_atom37_mask`: which of the 37 slots a token occupies.");
w(`inline const std::array<uint8_t, ${nTok * 37}> RESTYPE_ATOM37_MASK = {`);
const mask = UNIFIED_RESTYPE_ATOM37_MASK.flatMap((r) => Array.from(r));
for (let i = 0; i < mask.length; i += 37) w("    " + mask.slice(i, i + 37).join(",") + ",");
w("};");
w("");

w("// `get_allowed_residue_type_mask`: which residues a token TYPE admits.");
w(`inline const std::array<uint8_t, ${ALLOWED_RESIDUE_TYPES.length * nTok}> ALLOWED_RESIDUE_TYPES = {`);
for (const row of ALLOWED_RESIDUE_TYPES) w("    " + Array.from(row).join(",") + ",");
w("};");
w("");

w("// The 28 standard polymer residues, in the order the sequence-probability keys take.");
w(`inline const std::array<const char*, ${STANDARD_POLYMER_RESIDUES.length}> STANDARD_POLYMER_RESIDUES = {`);
w("    " + STANDARD_POLYMER_RESIDUES.map(str).join(", ") + ",");
w("};");
w("");

w("// The residues that carry a local latent (`supports_local_latent`).");
const latent = [...LOCAL_LATENT_RESIDUE_SET].sort();
w(`inline const std::array<const char*, ${latent.length}> LOCAL_LATENT_RESIDUES = {`);
for (let i = 0; i < latent.length; i += 8) w("    " + latent.slice(i, i + 8).map(str).join(", ") + ",");
w("};");
w("");

w("// The atom37 slot names, and which residues each token type admits.");
w(`inline const std::array<const char*, 37> ATOM37_NAMES = {`);
w("    " + ATOM37_NAMES.map(str).join(", ") + ",");
w("};");
w("");

w("enum TokenTypeId : int {");
for (const [k, v] of Object.entries(TokenType)) w(`  TT_${k} = ${v},`);
w("};");
w("");
w("inline const std::unordered_map<std::string, int> TOKEN_TYPE_IDS = {");
for (const [k, v] of Object.entries(TOKEN_TYPE_IDS)) w(`    {${str(k)}, ${v}},`);
w("};");
w("");
w("inline const std::unordered_map<std::string, std::vector<std::string>> RESIDUES_BY_TOKEN_TYPE = {");
for (const [k, names] of Object.entries(RESIDUES_BY_TOKEN_TYPE)) {
  w(`    {${str(k)}, {${names.map(str).join(", ")}}},`);
}
w("};");
w("");

w("enum ChainType : int {");
for (const [k, v] of Object.entries(CHAIN_TYPE)) if (typeof v === "number") w(`  CT_${k} = ${v},`);
w("};");
w("enum BondType : int {");
for (const [k, v] of Object.entries(BOND_TYPE)) if (typeof v === "number") w(`  BT_${k} = ${v},`);
w("};");
w("");
w("// The condition enums, by spec name then by member - what `C_SEC: {HELIX: ...}` resolves to.");
w("inline const std::unordered_map<std::string, std::unordered_map<std::string, int>> CONDITION_ENUMS = {");
for (const [name, members] of Object.entries(CONDITION_ENUMS)) {
  w(`    {${str(name)}, {${Object.entries(members).map(([k, v]) => `{${str(k)}, ${v}}`).join(", ")}}},`);
}
w("};");
w("");
w("// The 1-body condition registry: a spec key to its batch key, its dtype and its enum.");
// The default is what `sa_mask(...)` compares a value against: a number (a boolean as 0/1), a
// string, or neither (a coordinate's triple, whose mask has its own rule).
w("struct ConditionSpec {");
w("  const char* fullName; const char* dtype; const char* enumName;");
w("  bool defaultIsNum; double defaultNum; bool defaultIsStr; const char* defaultStr;");
w("};");
w("inline const std::unordered_map<std::string, ConditionSpec> CONDITION_REGISTRY = {");
const enumName = (e) => Object.entries(CONDITION_ENUMS).find(([, v]) => v === e)?.[0] ?? "";
const cNum = (v) => (Number.isNaN(v) ? "NAN" : String(v));
for (const [key, spec] of Object.entries(CONDITION_REGISTRY)) {
  const d = spec.default;
  const isNum = typeof d === "number" || typeof d === "boolean";
  const isStr = typeof d === "string";
  w(`    {${str(key)}, {${str(spec.fullName)}, ${str(spec.dtype)}, ${str(enumName(spec.enum))}, ` +
    `${isNum}, ${isNum ? cNum(Number(d)) : "NAN"}, ${isStr}, ${str(isStr ? d : "")}}},`);
}
w("};");
w("");
w("// 🔴 THE CATH LABEL -> EMBEDDING-ROW MAPS, PER LEVEL, AS UPSTREAM'S PICKLE HAS THEM");
w("// (shared/rfd4p/cath-mapping.js, generated from `data/cath_label_mapping.pkl`). They were a");
w("// hand-picked subset whose rows disagreed with the checkpoint's - `3.40.50` went in as");
w("// topology 890 where the model reads 1056.");
{
  const { CATH_CLASS_MAP, CATH_ARCHITECTURE_MAP, CATH_TOPOLOGY_MAP } =
    await import("../../../shared/rfd4p/conditions.js");
  for (const [name, table] of [["CATH_C", CATH_CLASS_MAP], ["CATH_A", CATH_ARCHITECTURE_MAP],
    ["CATH_T", CATH_TOPOLOGY_MAP]]) {
    w(`inline const std::unordered_map<std::string, int> ${name} = {`);
    const items = Object.entries(table).sort((x, y) => x[1] - y[1]);
    for (let i = 0; i < items.length; i += 6) {
      w("    " + items.slice(i, i + 6).map(([k, v]) => `{${str(k)}, ${v}}`).join(", ") + ",");
    }
    w("};");
  }
}
w("");
w("// The chemistry `parseCifToAtomArray` derives from a structure's own columns.");
w("inline const std::unordered_map<std::string, int> ELEMENT_TO_ATOMIC_NUMBER = {");
for (const [el, z] of Object.entries(ELEMENT_TO_ATOMIC_NUMBER)) w(`    {${str(el)}, ${z}},`);
w("};");
w("");
w("inline const std::unordered_set<std::string> METAL_ELEMENTS = {");
w("    " + [...METAL_ELEMENTS].map(str).join(", ") + ",");
w("};");
w("");
for (const [name, set] of [["AA_RESIDUES", AA_RESIDUES], ["RNA_RESIDUES", RNA_RESIDUES],
                           ["DNA_RESIDUES", DNA_RESIDUES]]) {
  w(`inline const std::unordered_set<std::string> ${name} = {`);
  const names = [...set];
  for (let i = 0; i < names.length; i += 10) w("    " + names.slice(i, i + 10).map(str).join(", ") + ",");
  w("};");
  w("");
}
w("// `<residue>:<atom>` -> the charge or the aromatic flag a standard residue carries.");
w("inline const std::unordered_map<std::string, int> STD_RESIDUE_CHARGES = {");
for (const [res, atoms] of Object.entries(STD_RESIDUE_CHARGES)) {
  for (const [atom, q] of Object.entries(atoms)) w(`    {${str(`${res}:${atom}`)}, ${q}},`);
}
w("};");
w("");
w("inline const std::unordered_set<std::string> STD_RESIDUE_AROMATIC = {");
for (const [res, atoms] of Object.entries(STD_RESIDUE_AROMATIC)) {
  w("    " + [...atoms].map((a) => str(`${res}:${a}`)).join(", ") + ",");
}
w("};");
w("");
w("// `_entity_poly.type` (lowercased) -> the chain type, as the reference maps it.");
w("inline const std::unordered_map<std::string, int> MMCIF_CHAIN_TYPE_MAP = {");
{
  const { readFileSync } = await import("node:fs");
  const src = readFileSync(new URL("../../../shared/rfd4p/pipeline/cif.js", import.meta.url), "utf8");
  const body = src.slice(src.indexOf("const MMCIF_CHAIN_TYPE_MAP = {"));
  for (const m of body.slice(0, body.indexOf("};")).matchAll(/'([^']+)':\s*CHAIN_TYPE\.(\w+)/g)) {
    w(`    {${str(m[1])}, CT_${m[2]}},`);
  }
}
w("};");
w("");
w("// The annotation columns a structure may carry, with the type and default each takes.");
w("struct AnnotationSpec { const char* type; int cols; double fallback; const char* text; };");
w("inline const std::unordered_map<std::string, AnnotationSpec> ANNOTATIONS_1BODY = {");
for (const [name, spec] of Object.entries(SCALAR_1BODY_ANNOTATIONS)) {
  const fb = typeof spec.default === "string" ? 0 : Number(spec.default);
  const text = typeof spec.default === "string" ? spec.default : "";
  w(`    {${str(name)}, {${str(spec.type)}, 1, ${fb}, ${str(text)}}},`);
}
for (const [name, spec] of Object.entries(NONSCALAR_1BODY_ANNOTATIONS)) {
  w(`    {${str(name)}, {${str(spec.type)}, ${spec.cols}, ${Number.isNaN(spec.default) ? "NAN" : spec.default}, ""}},`);
}
w("};");
w("");
w("// A standard residue's own bonds, as `<atom1>:<atom2>` with atom1 < atom2 and the bond type.");
w("inline const std::unordered_map<std::string, std::unordered_map<std::string, int>>");
w("    STD_RESIDUE_BONDS = {");
for (const [res, pairs] of Object.entries(STD_RESIDUE_BONDS)) {
  const entries = pairs.map(([a1, a2, bt]) =>
    `{${str(a1 < a2 ? `${a1}:${a2}` : `${a2}:${a1}`)}, ${bt}}`);
  w(`    {${str(res)}, {${entries.join(", ")}}},`);
}
w("};");
w("");
w("// `_chem_comp_bond.value_order:pdbx_aromatic_flag` and `_struct_conn.pdbx_value_order`.");
{
  const { readFileSync } = await import("node:fs");
  const src = readFileSync(new URL("../../../shared/rfd4p/pipeline/cif.js", import.meta.url), "utf8");
  for (const [name, decl] of [["COMP_BOND_ORDER_TO_TYPE", "const COMP_BOND_ORDER_TO_TYPE = {"],
                              ["STRUCT_CONN_ORDER_TO_TYPE", "const STRUCT_CONN_ORDER_TO_TYPE = {"]]) {
    const body = src.slice(src.indexOf(decl));
    w(`inline const std::unordered_map<std::string, int> ${name} = {`);
    for (const m of body.slice(0, body.indexOf("};")).matchAll(/'?([A-Za-z:]+)'?:\s*BOND_TYPE\.(\w+)/g)) {
      w(`    {${str(m[1])}, BT_${m[2]}},`);
    }
    w("};");
    w("");
  }
}
// 🔴 THE STEREOISOMER TEMPLATES ARE PRECOMPUTED, NOT BUILT AT START-UP. The reference enumerates
// every permutation of each ideal polyhedron and keeps the ones no rotation can carry onto an
// earlier one - up to 6! = 720 Kabsch fits per geometry, at module load. Generating them here
// makes the native side's start-up free and, more to the point, makes the SET a fact in the
// repository rather than something two implementations have to agree about.
w(`constexpr int MAX_OVERLAPPING_CENTERS = ${MAX_OVERLAPPING_CENTERS};`);
w("");
const pts = (p) => `{${p.map((v) => v.toExponential(17)).join(", ")}}`;
w("// `<geometry>:<n>` -> the distinct orderings of its first n ideal directions.");
w("inline const std::unordered_map<std::string, std::vector<std::vector<std::array<double, 3>>>>");
w("    STEREOISOMER_TEMPLATES = {");
for (const [key, reps] of STEREOISOMER_TEMPLATES) {
  w(`    {${str(key)}, {`);
  for (const rep of reps) w(`        {${rep.map(pts).join(", ")}},`);
  w("    }},");
}
w("};");
w("");
w("// `<side>:<nLeft>:<nRight>` -> the ideal planar arrangement of a stereogenic double bond.");
w("inline const std::unordered_map<std::string, std::vector<std::array<double, 3>>>");
w("    DOUBLE_BOND_TEMPLATES = {");
for (const [key, tpl] of DOUBLE_BOND_TEMPLATES) w(`    {${str(key)}, {${tpl.map(pts).join(", ")}}},`);
w("};");
w("");
w("inline const std::unordered_map<std::string, std::vector<std::array<double, 3>>>");
w("    IDEAL_POLYHEDRA = {");
for (const [geom, pointsList] of Object.entries(IDEAL_POLYHEDRA)) {
  w(`    {${str(geom)}, {${pointsList.map(pts).join(", ")}}},`);
}
w("};");
w("");
// 🔴 NOT EXPORTED BY THE REFERENCE, so it is read out of the source. A copy typed by hand would
// be a second place for a chiral centre to live, which is the one thing this generator exists to
// prevent; parsing the literal keeps it derived.
w("// A standard residue's own chiral centres: `<residue>:<atom>` -> the chiral type.");
w("inline const std::unordered_map<std::string, int> STD_POLYMER_CHIRAL_CENTERS = {");
{
  const { readFileSync } = await import("node:fs");
  const src = readFileSync(new URL("../../../shared/rfd4p/pipeline/chirality.js", import.meta.url),
                           "utf8");
  const start = src.indexOf("const STD_POLYMER_CHIRAL_CENTERS = {");
  const body = src.slice(start, src.indexOf("\n};", start));
  for (const line of body.split("\n").slice(1)) {
    const m = line.match(/^\s*(\w+):\s*\{(.*)\},?\s*$/);
    if (!m) continue;
    // 🔴 A NUCLEOTIDE'S CENTRES ARE QUOTED ATOM NAMES - `"C1'"` and its neighbours - so the
    // character class must admit the quote AND the apostrophe inside it. Without the double
    // quote the generator silently kept the twenty amino acids and dropped every nucleotide,
    // 21 entries where the source has 49.
    for (const e of m[2].matchAll(/["']?([A-Za-z0-9']+)["']?:\s*(\d+)/g)) {
      w(`    {${str(`${m[1]}:${e[1]}`)}, ${e[2]}},`);
    }
  }
}
w("};");
w("");
w("inline const std::unordered_map<std::string, int> CHIRAL_TYPE = {");
for (const [k, v] of Object.entries(CHIRAL_TYPE)) w(`    {${str(k)}, ${v}},`);
w("};");
w("");
// The backbone atom sets and the standard-residue sets `transforms.js` keeps privately. Read out
// of the source for `STD_POLYMER_CHIRAL_CENTERS`'s reason: not exported, and a hand copy is a
// second place for them to live.
{
  const { readFileSync } = await import("node:fs");
  const src = readFileSync(new URL("../../../shared/rfd4p/pipeline/transforms.js", import.meta.url),
                           "utf8");
  const setOf = (name) => {
    const at = src.indexOf(`const ${name} = new Set([`);
    if (at < 0) return null;
    const body = src.slice(at, src.indexOf("]);", at));
    // 🔴 BOTH QUOTE STYLES. A nucleic backbone atom is written `"O5'"` - double-quoted, because
    // its name contains an apostrophe - and a single-quote-only pattern reads straight through
    // it, producing garbage members like `", "C5`. The same trap as STD_POLYMER_CHIRAL_CENTERS,
    // one table later.
    return [...body.matchAll(/'([^']*)'|"([^"]*)"/g)].map((m) => m[1] ?? m[2]);
  };
  const protein = setOf("PROTEIN_BACKBONE_ATOMS");
  const rna = setOf("RNA_BACKBONE_ATOMS");
  const dna = setOf("DNA_BACKBONE_ATOMS");
  const na = [...new Set([...(rna ?? []), ...(dna ?? [])])];
  for (const [name, members] of [["PROTEIN_BACKBONE_ATOMS", protein],
                                 ["RNA_BACKBONE_ATOMS", rna],
                                 ["DNA_BACKBONE_ATOMS", dna],
                                 ["NA_BACKBONE_ATOMS", na]]) {
    w(`inline const std::unordered_set<std::string> ${name} = {`);
    w("    " + members.map(str).join(", ") + ",");
    w("};");
    w("");
  }
}
for (const [name, members] of [["STANDARD_AA", STANDARD_AA], ["STANDARD_RNA", STANDARD_RNA],
                               ["STANDARD_DNA", STANDARD_DNA]]) {
  w(`inline const std::unordered_set<std::string> ${name} = {`);
  w("    " + [...members].map(str).join(", ") + ",");
  w("};");
  w("");
}

// The recycle ("thinking") schedules, every name `recycleDepths` takes. They lived as a hand copy
// in src/schedule.h and its `high` was no upstream file - the second place for a convention.
w("// [width, depth] bands by name (shared/rfd4p/flow.js RECYCLE_SCHEDULES).");
w("inline const std::vector<std::pair<std::string, std::vector<std::pair<int, int>>>>& RECYCLE_SCHEDULES() {");
w("  static const std::vector<std::pair<std::string, std::vector<std::pair<int, int>>>> t = {");
for (const [name, bands] of Object.entries(RECYCLE_SCHEDULES)) {
  w(`      {${str(name)}, {${bands.map(([a, b]) => `{${a}, ${b}}`).join(", ")}}},`);
}
w("  };");
w("  return t;");
w("}");
w(`inline const char* DEFAULT_RECYCLE_SCHEDULE = ${str(DEFAULT_RECYCLE_SCHEDULE)};`);
w("");
// The WRITER's tables (shared/rfd4p/output.js): the order a residue's atoms are written in, as
// slots of its own atom37 layout, and the element symbols `inferElementSymbol` recognises - its
// own table (encoding.js), which is NOT cif.js's `ELEMENT_TO_ATOMIC_NUMBER` (62 against 94).
w("// `getOrderedAtomNamesForResidue`, as slots of each token's own layout: the write order.");
w(`inline const std::array<std::vector<int>, ${nTok}>& TOKEN_ATOM_ORDER() {`);
w(`  static const std::array<std::vector<int>, ${nTok}> t = {{`);
for (const tok of UNIFIED_ATOM37_TOKENS) {
  const slots = UNIFIED_ATOM37_ENCODING.token_slot_map[tok] ?? {};
  const order = getOrderedAtomNamesForResidue(tok).map((nm) => slots[nm]).filter((s) => s !== undefined);
  w(`      {${order.join(", ")}},`);
}
w("  }};");
w("  return t;");
w("}");
w("// `ATOMIC_NUMBER_BY_ELEMENT`'s symbols (encoding.js), which `inferElementSymbol` tests against.");
w("inline const std::unordered_set<std::string> INFER_ELEMENTS = {");
w("    " + Object.keys(ATOMIC_NUMBER_BY_ELEMENT).map(str).join(", ") + ",");
w("};");
w("");
w("// 🔴 THE TABLES UPSTREAM'S SELECTION LANGUAGE DERIVES ITS ANNOTATIONS FROM (atomworks' and");
w("// biotite's constants, through shared/rfd4p/pipeline/query-tables.js - see that file for their");
w("// BSD notices). `selection.h` reads these and nothing typed.");
{
  const Q = await import("../../../shared/rfd4p/pipeline/query-tables.js");
  const set = (name, values) => {
    w(`inline const std::unordered_set<std::string> Q_${name} = {`);
    for (let i = 0; i < values.length; i += 12) w("    " + values.slice(i, i + 12).map(str).join(", ") + ",");
    w("};");
  };
  for (const name of ["PROTEIN_BACKBONE_ATOM_NAMES", "RNA_BACKBONE_ATOM_NAMES", "DNA_BACKBONE_ATOM_NAMES",
    "NUCLEIC_ACID_BACKBONE_ATOM_NAMES", "STANDARD_AA", "STANDARD_RNA", "STANDARD_DNA",
    "PYRIMIDINE_RESIDUES", "PURINE_RESIDUES", "METAL_ELEMENTS", "CARBOHYDRATE_NAMES"]) set(name, [...Q[name]]);
  for (const name of ["UNKNOWN_AA", "UNKNOWN_RNA", "UNKNOWN_DNA", "MASKED"]) {
    w(`inline const std::string Q_${name} = ${str(Q[name])};`);
  }
  for (const name of ["PROTEIN_CHAIN_TYPES", "NUCLEIC_CHAIN_TYPES", "POLYMER_CHAIN_TYPES", "NON_POLYMER_CHAIN_TYPES"]) {
    w(`inline const std::unordered_set<int> Q_${name} = {${Q[name].join(", ")}};`);
  }
  for (const name of ["DNA", "RNA", "POLYPEPTIDE_L"]) w(`inline const int Q_CHAIN_${name} = ${Q.CHAIN_TYPE[name]};`);
  w("inline const std::unordered_map<std::string, std::unordered_set<std::string>> Q_TIP_ATOM_NAMES = {");
  for (const [res, names] of Object.entries(Q.TIP_ATOM_NAMES)) w(`    {${str(res)}, {${names.map(str).join(", ")}}},`);
  w("};");
}
w("}  // namespace tables");
w("}  // namespace rfd4p");

const text = out.join("\n") + "\n";
// `--check` is what the test runs: it compares rather than writes, so a stale file is a red gate
// and not a diff somebody has to notice.
if (process.argv.includes("--check")) {
  const { readFileSync } = await import("node:fs");
  const path = new URL("./tables.inc", import.meta.url).pathname;
  let have = "";
  try { have = readFileSync(path, "utf8"); } catch { /* absent counts as stale */ }
  if (have === text) {
    console.log("cuda/rfd4p/featurise/tables.inc is current");
    process.exit(0);
  }
  console.error("cuda/rfd4p/featurise/tables.inc is STALE - regenerate it:");
  console.error("  node cuda/rfd4p/featurise/gen-tables.mjs > cuda/rfd4p/featurise/tables.inc");
  process.exit(1);
}
process.stdout.write(text);
